async function ixAct(a,ds,t){const I=S.imp;if(a==="exportviewcsv"){exportCsvView();return}
 if(a==="imppaste"){S.impPaste=!S.impPaste;const b=$("#imp_pastebox");if(b){b.hidden=!S.impPaste;if(S.impPaste)$("#imp_paste")?.focus()}return}
 if(a==="imppasteread"){let txt=$("#imp_paste")?.value||"";if(!txt.trim()){try{txt=await navigator.clipboard.readText()}catch(_){}}if(!txt.trim()){toast("Paste the copied cells into the box first");return}S.impPaste=false;const b=$("#imp_pastebox");if(b)b.hidden=true;ixLoad([{name:"Pasted table",rows:ixParseText(txt)}],"Pasted table");return}
 if(!I)return;
 if(a==="impsheet"){I.active=+ds.i;if(!I.include.includes(I.active))I.include=[I.active];const sh=I.sheets[I.active];if(I.include.length===1&&!I.kindLocked){I.mem=ixApplyMemory(I,sh);I.kind=I.mem?.kind&&IXK[I.mem.kind]?I.mem.kind:sh.best}ixInitKind(I)}
 else if(a==="impdec"){if(ds.do==="undo")delete I.dec[ds.key];else ixDecide(I,ds.key,ds.do,ds.v)}
 else if(a==="impsim"){const u=I.preview.unk[ds.key];const d=I.dec[ds.key];if(u&&d)ixSimilar(I.preview,u).forEach(o=>{if(d.act==="use"||d.act==="skip"||d.act==="none")I.dec[o.key]={act:d.act,value:d.value,remember:d.remember};else{buildPreview();ixDecide(I,o.key,"new")}})}
 else if(a==="impgroup"){const us=Object.values(I.preview.unk).filter(u=>u.type===ds.type&&!u.dec);for(const u of us){if(ds.do==="skip")I.dec[u.key]={act:"skip",remember:true};else{ixDecide(I,u.key,"new");buildPreview()}}}
 else if(a==="impremember"){const d=I.dec[ds.key];if(d)d.remember=ds.v==="1"}
 else if(a==="impgrpall"){(I.preview.matches||[]).forEach(m=>I.grpAct[m.key]=ds.do)}
 else if(a==="impcsv"){ixCsvDownload(I,+ds.i);return}
 else if(a==="impall80"){const n=ixAcceptAll(I,.8);toast(`${n} suggestion${n===1?"":"s"} accepted`)}
 else if(a==="impfilter"){I.filter=ds.f;I.limit=100}else if(a==="impmore"){I.limit=(I.limit||100)+200}
 else if(a==="impedit"){I.editing=ds.e;renderImportPreview();return}
 buildPreview();renderImportPreview()}
function ixChange(t){const ds=t.dataset;const w=ds.ixc;
 if(w==="drvroot"){const d=ixDrv();d.root=t.value;d.path=[];ixDriveLoad();return}if(w==="drvtype"){ixDrv().type=t.value;ixDriveRender();return}if(w==="drvnew"){ixDrv().onlyNew=t.value==="1";ixDriveRender();return}
 if(w==="drvsel"){const d=ixDrv();const f=d.items.find(x=>x.id===ds.id);if(t.checked&&f)d.sel[f.id]=f;else delete d.sel[ds.id];ixDriveRender();return}if(w==="drvself"){const d=ixDrv();if(t.checked)d.selF[ds.id]={id:ds.id,name:ds.name};else delete d.selF[ds.id];ixDriveRender();return}
 const I=S.imp;if(!I)return;
 if(w==="totack"){I.totAck=t.checked;renderImportPreview();return}if(w==="totnote"){I.totNote=t.value;return}
 if(w==="include"){const i=+ds.i;if(t.checked){if(!I.include.includes(i))I.include.push(i);I.include.sort((a,b)=>a-b);const sh=I.sheets[i];ixMapSheet(I,sh,I.kind,ixApplyMemory(I,sh))}else{I.include=I.include.filter(x=>x!==i);if(!I.include.length)I.include=[I.active];if(!I.include.includes(I.active))I.active=I.include[0]}}
 else if(w==="def"){const v=t.value;if(v===""||v==null){delete I.def[ds.k];if(ds.k==="sh")I.def.sh=null}else I.def[ds.k]=t.type==="number"?+v:v;if(ds.k==="po")I.def.poAuto=false;if(ds.k==="party"&&I.kind==="pilines"){const pp=live(D.purchases).filter(p=>p.party===v&&!["closed","cancelled"].includes(p.status)).sort((a,b)=>(a.date||"")<(b.date||"")?1:-1)[0];if(pp)I.def.po=pp.no}}
 else if(w==="pick"){if(t.value)I.dec[ds.key]={act:"use",value:t.value,remember:I.dec[ds.key]?.remember!==false};else delete I.dec[ds.key]}
 else if(w==="draft"){const d=I.dec[ds.key];if(!d)return;d.draft={...(d.draft||{}),[ds.f]:t.type==="number"?(+t.value||1):t.value};if(ds.f==="sku")d.draft.sku=String(t.value).trim().toUpperCase().replace(/\s+/g,"-");if(ds.f==="brand"||ds.f==="category"){if(d.draft.brand&&d.draft.category&&!d.skuTouched){const r=ixReservedSkus(I);r.delete(d.draft.sku);d.draft.sku=ixSkuForR(d.draft.brand,d.draft.category,r)}}if(ds.f==="sku")d.skuTouched=true}
 else if(w==="remember"){const d=I.dec[ds.key];if(d)d.remember=t.checked;return}
 else if(w==="rowact"){I.rowAct[ds.r]=t.value}
 else if(w==="grpact"){I.grpAct[ds.g]=t.value}
 else if(w==="colact"){I.colAct[ds.h]=t.value}
 else if(w==="cell"){const[si,ri,c]=ds.e.split(":").map(Number);const k=si+":"+ri;const orig=I.sheets[si].data[ri][c];I.edits[k]=I.edits[k]||{};if(String(orig??"")===t.value)delete I.edits[k][c];else I.edits[k][c]=t.value;I.editing=null}
 buildPreview();renderImportPreview()}

