const IX_SERIAL=/^(no|#|s ?n|sn|sr|sr no|serial|serial no|carton no|carton number|item no|line|line no|row|idx|index|nr)$/;
function ixColKey(I){const sh=I.sheets[I.active];return I.fixed?.fmt?"fmt:"+I.fixed.fmt+(I.def.party?":"+I.def.party:""):sh.source?.key?"src:"+sh.source.key:sh.meta?.party?"party:"+sh.meta.party:"sig:"+sh.sig}
function ixColDefaults(I){I.colWhy=I.colWhy||{};const MM=ixMem();const rem=MM.cols?.[ixColKey(I)]||{};I.sheets.forEach(sh=>sh.hn.forEach(h=>{if(!h)return;const a=I.colAct[h];if(a==="keep"||a==="skip")return;if(a)I.colAct[h]=/^keep/.test(a)?"keep":"skip";else if(rem[h]){I.colAct[h]=rem[h];I.colWhy[h]="remembered"}else if(MM.ignore?.[h]){I.colAct[h]="skip";I.colWhy[h]="remembered"}else if(MM.keep?.[h]){I.colAct[h]="keep";I.colWhy[h]="remembered"}}))}
