function ixColType(sh,c){const vals=sh.data.map(r=>r[c]).filter(v=>v!==""&&v!=null).slice(0,60);if(!vals.length)return"text";if(vals.every(v=>/^https?:\/\//i.test(String(v).trim())))return"link";if(vals.every(v=>ixNum(v).v!=null))return"num";if(vals.every(v=>/^\d{4}-\d{2}-\d{2}/.test(String(v))))return"date";return vals.some(v=>String(v).length>80)?"textarea":"text"}
function ixColsHtml(I,sh){const unused=ixUnused(I,sh);if(!unused.length)return`<aside class="card ixside" id="ix_cols"><div class="card-h"><h2>Extra columns</h2></div><div class="status" style="padding:10px 14px">Every column is used.</div></aside>`;
 const form=IX_FORM[I.kind];const st=unused.map(([h,i])=>({h,i,hn:sh.hn[i],...ixColState(I,sh,i),ex:sh.data.find(r=>r[i]!==""&&r[i]!=null)?.[i]}));const nk=st.filter(x=>x.a==="keep").length;
 return`<aside class="card ixside" id="ix_cols"><div class="card-h"><h2>Not needed / new columns (${unused.length})</h2></div><div style="padding:8px 14px 0" class="status">Kept columns are saved as custom fields on the ${esc(form?IX_REC[form]:"import record")}${form?` (Setup › Forms › ${esc(form)})`:""}. Your choice is remembered for this ${I.fixed?"format":sh.source?"report":"supplier / layout"}.</div>
 <div class="ixbar" style="padding:8px 14px"><button class="btn sm" data-ixa="colall" data-v="keep">Keep all with data</button><button class="btn sm" data-ixa="colall" data-v="skip">Skip all</button><span class="status">${nk} kept</span></div>
 <div class="ixcols">${st.map(x=>`<div class="ixcol ${x.a}"><div class="n"><b title="${esc(x.h)}">${esc(ixShort(x.h,40))}</b><span class="ixchip ${x.why==="remembered"||x.why==="you"?"ixc-r":x.a==="keep"?"ixc-h":"ixc-m"}">${esc(x.why)}</span>${x.ex!=null?`<span class="ex">e.g. ${esc(ixShort(x.ex,40))}</span>`:""}</div><div class="ixacts" role="group" aria-label="Column ${esc(x.h)}"><button class="chipb ${x.a==="keep"?"on":""}" data-ixa="col" data-h="${esc(x.hn)}" data-v="keep" aria-pressed="${x.a==="keep"}">Keep</button><button class="chipb ${x.a==="skip"?"on":""}" data-ixa="col" data-h="${esc(x.hn)}" data-v="skip" aria-pressed="${x.a==="skip"}">Skip</button></div></div>`).join("")}</div></aside>`}
function ixKeptCols(I){const out=[];const seen=new Set();I.include.forEach(si=>{const sh=I.sheets[si];ixUnused(I,sh).forEach(([h,i])=>{if(seen.has(h))return;if(ixColState(I,sh,i).a!=="keep")return;seen.add(h);out.push({h,hn:sh.hn[i],t:ixColType(sh,i)})})});return out}
async function ixMakeCustom(I){const kept=ixKeptCols(I);I.colKeys={};if(!kept.length)return;const form=IX_FORM[I.kind];const cfg=SET().forms?.[form]||{};const cu=(cfg.custom||[]).slice();let ch=false;
 kept.forEach(({h,hn,t})=>{let f=cu.find(x=>x.src===hn||ixNorm(x.l)===hn);if(!f){let base="x_"+(ixKey(h).replace(/[^a-z0-9]/g,"").slice(0,24)||"col");let k=base,n=2;while(cu.some(x=>x.k===k))k=base+n++;f={k,l:String(h).slice(0,60),t,src:hn,fromImport:true};cu.push(f);ch=true}I.colKeys[h]=f.k});
 if(form&&ch)await setupPatch(["forms",form,"custom"],cu,null)}
function ixDocX(x){if(!x||!Object.keys(x).length)return{};const K=S.imp?.colKeys||{};const c={};Object.entries(x).forEach(([h,v])=>{c[K[h]||("x_"+ixKey(h).slice(0,24))]=v});return{custom:c}}
function ixCustomOf(x){return ixDocX(x).custom||null}

/* ---------- Drive picker ---------- */
const IX_FTYPES=[["all","All files"],["pi","PI / CI (supplier invoices)"],["pack","Packing info"],["freight","Freight invoices"],["receipt","Receipts"],["market","Marketplace reports"],["bank","Bank statements"]];
function ixFType(f){const n=String(f.name||"");const m=String(f.mimeType||"");if(/^image\//.test(m)||/\.(jpe?g|png|heic|webp|gif)$/i.test(n)||/receipt|payment proof|transfer/i.test(n))return"receipt";if(/packing|product[_ ]?information|packing[_ ]?list/i.test(n))return"pack";if(/freight|logistics|forwarder|shipping[_ ]?invoice|^SQ-|invoice_SQ|eco|yucheng/i.test(n))return"freight";
 if(/\b(PI|CI)\b|[_ -](PI|CI)[_ -]|^(PI|CI)[_ -]|proforma|commercial[_ ]invoice|WAP-/i.test(n))return"pi";if(/statement|wise|worldfirst|bank|barclays|lloyds/i.test(n))return"bank";if(/report|listing|orders?|transaction|settlement|dashboard|order_export|taxreport|all_orders/i.test(n)||m==="application/vnd.google-apps.spreadsheet")return"market";return"other"}
const ixIsFolder=f=>f.mimeType==="application/vnd.google-apps.folder";
function ixDriveOk(){return!!(window.MYTOOL&&MYTOOL.drive&&(!MYTOOL.demo||window.__DEMO_DRIVE))}
function ixDrv(){return S.impDrive||(S.impDrive={open:false,root:"root",path:[],items:[],sel:{},selF:{},onlyNew:true,type:"all",loading:false,err:null})}
async function ixDriveLoad(){const d=ixDrv();if(!ixDriveOk()){ixDriveRender();return}d.loading=true;d.err=null;ixDriveRender();const parent=d.path.length?d.path[d.path.length-1].id:d.root;
 try{const list=await MYTOOL.drive.list(parent,{});d.items=(list||[]).slice().sort((a,b)=>(ixIsFolder(b)-ixIsFolder(a))||String(a.name).localeCompare(String(b.name)))}catch(e){d.err=e.message||"Drive did not answer";d.items=[]}d.loading=false;ixDriveRender()}
function ixDriveSince(fid){return ixMem().drive?.last?.[fid]||null}
function ixDriveFileOk(d,f,fid){if(ixIsFolder(f))return false;if(d.type!=="all"&&ixFType(f)!==d.type)return false;if(d.onlyNew){const s=ixDriveSince(fid);if(s&&f.modifiedTime&&f.modifiedTime<=s)return false}return true}
function ixDriveHtml(){const d=ixDrv();if(!d.open)return"";if(!ixDriveOk())return`<div class="card" id="ix_drive"><div class="card-h"><h2>From Google Drive</h2><button class="btn sm" data-ixa="drvclose">Close</button></div><div class="note" style="padding:12px 14px">Drive works when signed in — open MY TOOL with your Google account (not the demo) and the folders appear here.</div></div>`;
 const fid=d.path.length?d.path[d.path.length-1].id:d.root;const folders=d.items.filter(ixIsFolder),files=d.items.filter(f=>!ixIsFolder(f));const shown=files.filter(f=>ixDriveFileOk(d,f,fid));const nSel=Object.keys(d.sel).length+Object.keys(d.selF).length;const last=ixMem().drive?.folders||[];
 const crumbs=[`<button class="btn sm" data-ixa="drvroot" data-v="${esc(d.root)}">${d.root==="shared"?"Shared with me":"My Drive"}</button>`].concat(d.path.map((p,i)=>`<button class="btn sm" data-ixa="drvup" data-i="${i}">${esc(ixShort(p.name,24))}</button>`)).join(" › ");
 return`<div class="card" id="ix_drive"><div class="card-h"><h2>From Google Drive</h2><button class="btn sm" data-ixa="drvclose">Close</button></div><div style="padding:10px 14px;display:flex;flex-direction:column;gap:8px">
 <div class="ixbar"><label class="status">Drive <select data-ixc="drvroot" aria-label="Which Drive"><option value="root" ${d.root==="root"?"selected":""}>My Drive</option><option value="shared" ${d.root==="shared"?"selected":""}>Shared with me</option></select></label>
 <label class="status">Files <select data-ixc="drvtype" aria-label="File type">${optsHtml(IX_FTYPES,d.type)}</select></label><label class="status">Show <select data-ixc="drvnew" aria-label="New or all"><option value="1" ${d.onlyNew?"selected":""}>Only new since last import</option><option value="0" ${d.onlyNew?"":"selected"}>All files</option></select></label></div>
 ${last.length?`<div class="ixbar"><span class="status">Last folders:</span>${last.slice(0,6).map(f=>`<button class="btn sm" data-ixa="drvgo" data-id="${esc(f.id)}" data-name="${esc(f.name)}" data-root="${esc(f.root||"root")}">${esc(ixShort(f.name,26))}</button>`).join("")}</div>`:""}
 <div class="ixbar" style="flex-wrap:wrap">${crumbs}</div>${d.err?`<div class="badbox">${esc(d.err)}</div>`:""}${d.loading?`<div class="status">Loading…</div>`:""}
 <div class="ixdrv">${folders.map(f=>`<div class="ixdi"><input type="checkbox" data-ixc="drvself" data-id="${esc(f.id)}" data-name="${esc(f.name)}" ${d.selF[f.id]?"checked":""} aria-label="Select folder ${esc(f.name)}"><button class="lnk" data-ixa="drvopen" data-id="${esc(f.id)}" data-name="${esc(f.name)}">📁 ${esc(f.name)}</button></div>`).join("")}
 ${shown.map(f=>`<div class="ixdi"><input type="checkbox" data-ixc="drvsel" data-id="${esc(f.id)}" ${d.sel[f.id]?"checked":""} aria-label="Select ${esc(f.name)}"><span class="n">${esc(f.name)} <small class="status">${esc((IX_FTYPES.find(t=>t[0]===ixFType(f))||["","other"])[1])}${f.modifiedTime?` · ${esc(fmtD(f.modifiedTime.slice(0,10)))}`:""}</small></span></div>`).join("")}
 ${!d.loading&&!folders.length&&!shown.length?`<div class="status">${files.length?`${files.length} file${files.length===1?"":"s"} hidden by the filters`:"Empty folder"}</div>`:""}</div>
 <div class="ixbar"><button class="btn pri" data-ixa="drvimport" ${nSel?"":"disabled"}>Import selected (${nSel})</button><span class="status">Ticked folders: every matching file inside (and sub-folders) — one after another.</span></div></div></div>`}
function ixDriveRender(){const b=$("#ix_drivebox");if(b)b.innerHTML=ixDriveHtml()}
async function ixDriveCollect(d){const out=[];const seen=new Set();const add=(f,fid)=>{if(seen.has(f.id))return;seen.add(f.id);out.push({id:f.id,name:f.name,mime:f.mimeType,src:"drive",folder:fid,st:"wait"})};
 Object.values(d.sel).forEach(f=>add(f,null));const walk=async(fid,depth,top)=>{let list=[];try{list=await MYTOOL.drive.list(fid,{})}catch(e){toast("Drive: "+e.message);return}for(const f of list||[]){if(ixIsFolder(f)){if(depth<3)await walk(f.id,depth+1,top)}else if(ixDriveFileOk(d,f,top))add(f,top)}};
 for(const f of Object.values(d.selF))await walk(f.id,0,f.id);return out}
async function ixDriveImport(){const d=ixDrv();const items=await ixDriveCollect(d);if(!items.length){toast("Nothing to import — no matching files (try “All files”)");return}
 const MM=ixMem();const dr={...(MM.drive||{})};const now=new Date().toISOString();dr.last={...(dr.last||{})};const fl=(dr.folders||[]).filter(f=>!d.selF[f.id]);Object.values(d.selF).forEach(f=>{dr.last[f.id]=now;fl.unshift({id:f.id,name:f.name,root:d.root})});if(d.path.length&&Object.keys(d.sel).length){const cf=d.path[d.path.length-1];dr.last[cf.id]=now;if(!fl.some(f=>f.id===cf.id))fl.unshift({id:cf.id,name:cf.name,root:d.root})}dr.folders=fl.slice(0,8);
 try{await setupPatch(["importMemory","drive"],dr,null)}catch(e){console.warn(e)}d.open=false;d.sel={};d.selF={};ixDriveRender();ixQStart(items)}

/* ---------- file queue (several uploads or Drive files, one after another) ---------- */
function ixQStart(items){S.impQ={items,busy:false};S.imp=null;ixQRender();const o=$("#imp_out");if(o)o.innerHTML="";ixQNext()}
async function ixQNext(){const Q=S.impQ;if(!Q||Q.busy)return;const it=Q.items.find(x=>x.st==="wait");if(!it){Q.cur=null;ixQRender();return}Q.busy=true;it.st="loading";Q.cur=it;ixQRender();
 try{let file=it.file;if(!file){const blob=await MYTOOL.drive.download(it.id,it.mime);if(!blob)throw new Error("Drive returned no file");file=blob instanceof File?blob:new File([blob],it.name,{type:blob.type||""})}const r=await handleImport(file);if(r.ok)it.st="ready";else if(r.proof){it.st="proof";it.msg=r.msg}else{it.st="error";it.msg=r.msg}}
 catch(e){console.error(e);it.st="error";it.msg=e.message||"could not be read"}Q.busy=false;ixQRender();if(it.st!=="ready"){Q.cur=null;return ixQNext()}}
function ixQRender(){const b=$("#ix_qbox");if(!b)return;const Q=S.impQ;if(!Q||!Q.items.length){b.innerHTML="";return}const L={wait:"waiting",loading:"reading…",ready:"in preview — check and Import, or skip",imported:"imported",skipped:"skipped",error:"could not be read",proof:"attach as proof only"};const cls={imported:"p-ok",ready:"p-warn",error:"p-bad",proof:"p-mute",skipped:"p-mute",wait:"p-mute",loading:"p-warn"};
 const done=Q.items.filter(x=>!["wait","loading","ready"].includes(x.st)).length;b.innerHTML=`<div class="card" id="ix_queue"><div class="card-h"><h2>Files (${done} of ${Q.items.length} done)</h2><div class="ixacts">${Q.cur&&Q.cur.st==="ready"?`<button class="btn sm" data-ixa="qskip">Skip this file</button>`:""}<button class="btn sm" data-ixa="qclear">Clear list</button></div></div><div class="ixq">${Q.items.map(x=>`<div class="ixqi"><span class="pill ${cls[x.st]||""}">${esc(L[x.st]||x.st)}</span><span class="n">${esc(x.name)}${x.imp?` → <b class="num">${esc(x.imp)}</b>`:""}${x.msg?`<br><small class="status">${esc(x.msg)}</small>`:""}</span></div>`).join("")}</div></div>`}
function ixQAfterImport(no){const Q=S.impQ;if(!Q||!Q.cur)return false;Q.cur.st="imported";Q.cur.imp=no;Q.cur=null;return true}

/* ---------- own event listeners (data-ixa clicks, multi-file input, drop) — no edits to events.js needed ---------- */
document.addEventListener("click",async e=>{const t=e.target.closest("[data-ixa]");if(!t)return;const a=t.dataset.ixa,ds=t.dataset;const I=S.imp;
 try{if(a==="drive"){const d=ixDrv();d.open=!d.open;ixDriveRender();if(d.open&&ixDriveOk()&&!d.items.length)await ixDriveLoad();return}
  if(a==="drvclose"){ixDrv().open=false;ixDriveRender();return}if(a==="drvopen"){const d=ixDrv();d.path.push({id:ds.id,name:ds.name});await ixDriveLoad();return}if(a==="drvup"){const d=ixDrv();d.path=d.path.slice(0,+ds.i+1);await ixDriveLoad();return}if(a==="drvroot"){const d=ixDrv();d.path=[];await ixDriveLoad();return}
  if(a==="drvgo"){const d=ixDrv();d.root=ds.root||"root";d.path=[{id:ds.id,name:ds.name}];await ixDriveLoad();return}if(a==="drvimport"){await ixDriveImport();return}
  if(a==="qskip"){const Q=S.impQ;if(Q?.cur){Q.cur.st="skipped";Q.cur=null}S.imp=null;const o=$("#imp_out");if(o)o.innerHTML="";ixQRender();ixQNext();return}if(a==="qclear"){S.impQ=null;ixQRender();return}
  if(!I)return;if(a==="col"){I.colAct[ds.h]=ds.v;I.colWhy=I.colWhy||{};I.colWhy[ds.h]="you"}else if(a==="colall"){const sh=I.sheets[I.active];ixUnused(I,sh).forEach(([h,i])=>{const hn=sh.hn[i];if(ds.v==="skip"||sh.data.some(r=>r[i]!==""&&r[i]!=null)){I.colAct[hn]=ds.v;I.colWhy=I.colWhy||{};I.colWhy[hn]="you"}})}
  buildPreview();renderImportPreview()}catch(err){console.error(err);toast(err.message||"Something went wrong")}});
document.addEventListener("change",e=>{const t=e.target;if(t.id!=="imp_file"||!t.files||t.files.length<2)return;e.stopImmediatePropagation();const items=[...t.files].map(f=>({name:f.name,file:f,src:"upload",st:"wait"}));t.value="";ixQStart(items)},true);
document.addEventListener("change",e=>{const t=e.target;if(t.id==="imp_file")setTimeout(()=>{try{t.value=""}catch(_){}},0)});
document.addEventListener("dragover",e=>{if(e.target.closest&&e.target.closest(".dz")){e.preventDefault()}});
document.addEventListener("drop",e=>{const z=e.target.closest&&e.target.closest(".dz");if(!z)return;e.preventDefault();const fs=[...(e.dataTransfer?.files||[])];if(!fs.length)return;if(fs.length===1)handleImport(fs[0]);else ixQStart(fs.map(f=>({name:f.name,file:f,src:"upload",st:"wait"})))});

/* ---------- commit for the new kinds (called from runImport) ---------- */
const IXCOMMIT={
 async cipart(I,P,R,impNo,out){const pl=P.plan.part;if(!pl)return 0;const po=D.purchases.find(p=>p.no===pl.po);if(!po)return 0;const before=JSON.parse(JSON.stringify(po));const part={...pl.part,lines:pl.part.lines.map(l=>{const{x,...rest}=l;return{...rest,sku:R(l.sku)||null,...(x?{custom:ixCustomOf(x)}:{})}}),import:impNo,at:nowIso()};
  const xs=pl.part.lines.reduce((a,l)=>ixMergeX(a,l.x),null);if(xs)part.custom=ixCustomOf(xs);await updateDoc("purchases",po.no,{parts:[...(po.parts||[]),part],notes:((po.notes?po.notes+" · ":"")+`part invoice ${part.no} (${part.ctn} ctn, ${part.units} units) linked by ${impNo}`).slice(0,600)},null,{quiet:true});out.updates.push({col:"purchases",id:po.no,before});await ixAsinLinks(I,P,R,out,pl.part.lines);return 1},
 async packinfo(I,P,R,impNo,out){let n=0;for(const{sku,patch}of P.plan.prodPatch||[]){const p=product(sku);if(!p)continue;const before=JSON.parse(JSON.stringify(p));const pt={...patch};if(pt.custom){const c={};Object.entries(pt.custom).forEach(([k,v])=>{if(k.startsWith("§col:")){const h=k.slice(5);c[I.colKeys?.[h]||("x_"+ixKey(h).slice(0,24))]=v}else c[k]=v});pt.custom=c}
   await updateDoc("products",p.id||p.sku,pt,null,{quiet:true});out.updates.push({col:"products",id:p.id||p.sku,before});n++}
  const f=P.plan.shFill;if(f){const sh=D.shipments.find(s=>s.no===f.sh);if(sh){const before=JSON.parse(JSON.stringify(sh));await updateDoc("shipments",sh.no,{...f.patch,notes:((sh.notes?sh.notes+" · ":"")+`lines from packing list ${I.file||""} (${impNo})`).slice(0,600)},null,{quiet:true});out.updates.push({col:"shipments",id:sh.no,before});n++}}return n},
 async listings(I,P,R,impNo,out){let n=0;for(const b of P.plan.listings||[]){const sku=R(b.sku);const p=product(sku);if(!p)continue;const before=JSON.parse(JSON.stringify(p));const patch={listings:[...(p.listings||[]),...b.add.map(l=>{const{x,...rest}=l;return{...rest,...(x?{custom:ixCustomOf(x)}:{}),import:impNo}})]};if(b.asin&&!p.asin)patch.asin=b.asin;await updateDoc("products",p.id||p.sku,patch,null,{quiet:true});out.updates.push({col:"products",id:p.id||p.sku,before});n++}
  const al=P.plan.aliases||{};if(Object.keys(al).length){const SA={...(SET().skuAliases||{})};Object.entries(al).forEach(([a,s])=>{const v=R(s);if(v)SA[a]=v});await setupPatch("skuAliases",SA,null)}return n},
 async dashboard(I,P,R,impNo,out){const M=P.plan.statsMeta;let n=0;for(const a of P.plan.stats||[]){const no=nextNo("salesStats",M.to);await writeDoc("salesStats",no,{no,type:"dashboard",sku:null,marketplace:M.mk,from:M.from,to:M.to,days:a.days,units:a.units,sales:a.sales,orderItems:a.orderItems,daily:a.daily,source:"amazon_dashboard",import:impNo},null);out.docIds.push("salesStats:"+no);n++}return n},
 async taxreport(I,P,R,impNo,out){const M=P.plan.statsMeta;let n=0;for(const a of P.plan.stats||[]){const sku=R(a.sku);if(!sku)continue;const no=nextNo("salesStats",M.to);await writeDoc("salesStats",no,{no,type:"tax",sku,marketplace:a.marketplace,from:M.from,to:M.to,days:diffDays(M.from,M.to)+1,units:a.units,returns:a.returns,salesIncl:r2(a.incl),vat:r2(a.vat),salesExcl:r2(a.excl),shipIncl:r2(a.shipIncl),shipVat:r2(a.shipVat),orders:a.orders,import:impNo},null);out.docIds.push("salesStats:"+no);n++}return n},
 async dispatch(){return 1},async adsbill(){return 1}
};
/* ASINs read from a supplier / forwarder document are saved on the product (so the next file needs no table) */
async function ixAsinLinks(I,P,R,out,lines){for(const l of lines||[]){const sku=R(l.sku);const a=String(l.asin||"").toUpperCase();if(!sku||!RD_ASIN_RE.test(a))continue;const p=product(sku);if(!p||p.asin||(p.listings||[]).some(x=>String(x.id||"").toUpperCase()===a))continue;if(out.updates.some(u=>u.col==="products"&&u.id===(p.id||p.sku))){await updateDoc("products",p.id||p.sku,{asin:a},null,{quiet:true});continue}const before=JSON.parse(JSON.stringify(p));await updateDoc("products",p.id||p.sku,{asin:a},null,{quiet:true});out.updates.push({col:"products",id:p.id||p.sku,before})}}

const IXCSS2=`.ixlay{display:grid;grid-template-columns:minmax(0,1fr) minmax(250px,310px);gap:12px;align-items:start;min-width:0}.ixmain{display:flex;flex-direction:column;gap:12px;min-width:0}.ixside{position:sticky;top:8px;max-height:calc(100vh - 24px);overflow:auto;min-width:0}
@media (max-width:980px){.ixlay{grid-template-columns:minmax(0,1fr)}.ixside{position:static;max-height:none}}
.ixcols{display:flex;flex-direction:column;gap:6px;padding:4px 14px 12px}.ixcol{border:1px solid var(--line);border-radius:8px;padding:6px 8px;display:flex;flex-direction:column;gap:4px;min-width:0;background:var(--panel)}.ixcol.skip{opacity:.7}.ixcol .n{display:flex;flex-wrap:wrap;gap:4px 6px;align-items:center;min-width:0;overflow-wrap:anywhere}.ixcol .ex{font:11.5px var(--f-data);color:var(--muted);flex-basis:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ixtot{font-size:13px;overflow-wrap:anywhere}.ixtot.bad{color:var(--bad)}.ixtot.warn{color:var(--warn)}.ixfx{padding:0 14px 12px;font-size:13px;overflow-wrap:anywhere}
.ixdrv{display:flex;flex-direction:column;gap:2px;max-height:360px;overflow:auto;border:1px solid var(--line);border-radius:8px;padding:6px}.ixdi{display:flex;gap:8px;align-items:center;min-width:0;padding:3px 2px}.ixdi .n,.ixdi .lnk{flex:1;min-width:0;overflow-wrap:anywhere;text-align:left;background:none;border:0;padding:0;color:var(--fg);font:inherit;cursor:pointer}
.ixq{display:flex;flex-direction:column;gap:4px;padding:8px 14px 12px}.ixqi{display:flex;gap:8px;align-items:flex-start;min-width:0}.ixqi .n{flex:1;min-width:0;overflow-wrap:anywhere}.ixqi .pill{flex:none}`;
function ixCss2(){if(document.getElementById("impcss2"))return;const s=document.createElement("style");s.id="impcss2";s.textContent=IXCSS2;document.head.appendChild(s)}
